public int collatzLength(long n) {
    if (n < 1) {
        throw new IllegalArgumentException("n must be positive");
    }
    int steps = 0;
    while (n != 1) {
        if (n % 2 == 0) {
            n /= 2;
        } else {
            n = 3 * n + 1;   // long math — 3n+1 can spike above int range
        }
        steps++;
    }
    return steps;
}

