private final Map<Long, Integer> cache = new HashMap<>();

public int collatzLength(long n) {
    if (n == 1) {
        return 0;
    }
    Integer cached = cache.get(n);
    if (cached != null) {
        return cached;
    }
    long next = (n % 2 == 0) ? n / 2 : 3 * n + 1;
    int result = 1 + collatzLength(next);
    cache.put(n, result);
    return result;
}

code.python:
from functools import lru_cache

class Solution:
    @lru_cache(maxsize=None)
    def collatz_length(self, n: int) -> int:
        if n == 1:
            return 0
        nxt = n // 2 if n % 2 == 0 else 3 * n + 1
        return 1 + self.collatz_length(nxt)

